#!/usr/bin/env bash
# Question 7: Back up etcd. Generated by Quick Create; variables arrive as environment variables.
set -euo pipefail

rm -f "${Q7_BACKUP}"
mkdir -p "$(dirname "${Q7_BACKUP}")"
kubectl -n default create configmap "${Q7_MARKER}" --from-literal=created="$(date -Is)" --dry-run=client -o yaml | kubectl apply -f - >/dev/null
rm -f "${Q7_STATUS_FILE}"
